-- 자동 생성 파일입니다. 고치지 말고 pnpm db:seed:generate로 다시 만듭니다.
begin;
set constraints all deferred;
insert into public.pantheons (slug, name, name_en, region, earliest_source, era_label, era_year, summary, description, cover_exhibit_id)
select slug, name, name_en, region, earliest_source, era_label, era_year, summary, description, cover_exhibit_id from jsonb_populate_recordset(null::public.pantheons, $seed$[{"slug":"egyptian","name":"이집트 신화","name_en":"Egyptian","region":"나일강 유역","earliest_source":"피라미드 텍스트","era_label":"기원전 24세기경","era_year":-2400,"summary":"죽음 이후의 삶과 심판, 태양의 순환을 중심으로 삼천 년 넘게 이어진 신화입니다.","description":["이집트 신화는 나일강의 범람과 태양의 운행처럼 되풀이되는 자연의 질서를 신들의 이야기로 풀어냈습니다.","왕의 무덤 벽에 새긴 피라미드 텍스트에서 시작해 관 텍스트, 사자의 서로 이어지며 죽은 이가 저승을 지나 심판을 받는 과정이 자세히 기록되었습니다."],"cover_exhibit_id":"weighing-heart"},{"slug":"mesopotamian","name":"메소포타미아 신화","name_en":"Mesopotamian","region":"티그리스·유프라테스강 유역","earliest_source":"수메르어 길가메시 시가","era_label":"기원전 21세기경","era_year":-2100,"summary":"점토판에 쐐기문자로 새긴, 인류가 남긴 가장 오래된 영웅 서사가 있는 신화입니다.","description":["수메르, 아카드, 바빌로니아, 아시리아로 이어진 도시 문명들은 신들을 도시의 수호자로 섬겼습니다.","죽음을 피하려 길을 떠난 길가메시의 이야기와 혼돈의 바다를 무찌르고 세계를 세운 마르두크의 창조 서사시 「에누마 엘리시」가 대표적입니다."],"cover_exhibit_id":"ishtar-gate-lion"},{"slug":"hindu","name":"인도 신화","name_en":"Hindu","region":"인도 아대륙","earliest_source":"리그베다","era_label":"기원전 15세기경","era_year":-1500,"summary":"창조와 유지, 파괴가 끝없이 되풀이되는 우주관 위에 수많은 신과 화신이 등장합니다.","description":["베다의 찬가에서 시작한 인도 신화는 「마하바라타」, 「라마야나」 같은 서사시와 푸라나 문헌으로 넓어졌습니다.","세계를 유지하는 비슈누와 파괴와 재생의 신 시바, 지혜와 시작의 신 가네샤처럼 지금도 널리 숭배되는 신들이 많습니다."],"cover_exhibit_id":"shiva-nataraja"},{"slug":"greek","name":"그리스 신화","name_en":"Greek","region":"에게해 연안","earliest_source":"호메로스 「일리아스」·「오디세이아」","era_label":"기원전 8세기경","era_year":-800,"summary":"올림포스의 열두 신과 영웅들의 이야기로, 서양 예술과 문학의 뿌리가 된 신화입니다.","description":["그리스 신화의 신들은 사람처럼 사랑하고 질투하며 다툽니다. 호메로스와 헤시오도스의 서사시가 그 이야기를 처음 글로 남겼습니다.","로마는 그리스의 신들을 자기 신들과 동일시해 받아들였고, 로마 시대에 만든 대리석 모작 덕분에 사라진 그리스 원작의 모습을 지금도 볼 수 있습니다."],"cover_exhibit_id":"artemision-bronze"},{"slug":"japanese","name":"일본 신화","name_en":"Japanese","region":"일본 열도","earliest_source":"「고사기」","era_label":"712년","era_year":712,"summary":"천지가 열리고 섬들이 태어나는 이야기에서 시작해 태양신의 후손으로 이어지는 신화입니다.","description":["712년에 엮은 「고사기」와 720년의 「일본서기」에 이자나기와 이자나미의 국토 창조, 아마테라스와 스사노오의 이야기가 실려 있습니다.","에도 시대와 메이지 시대의 우키요에 화가들은 이 장면들을 목판화로 즐겨 그렸습니다."],"cover_exhibit_id":"amaterasu-iwato"},{"slug":"norse","name":"북유럽 신화","name_en":"Norse","region":"스칸디나비아·아이슬란드","earliest_source":"「산문 에다」·「시 에다」","era_label":"13세기","era_year":1220,"summary":"거인과 싸우는 신들, 그리고 피할 수 없는 종말 라그나로크로 끝나는 신화입니다.","description":["북유럽 신화는 오랫동안 입으로 전해지다가 13세기 아이슬란드에서 스노리 스튀르류손의 「산문 에다」와 「시 에다」로 기록되었습니다.","19세기 낭만주의 시대에 스칸디나비아 화가들이 오딘과 토르를 다시 그리면서 오늘날 우리가 떠올리는 북유럽 신들의 모습이 만들어졌습니다."],"cover_exhibit_id":"thor-jotnar"}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.figures (slug, pantheon_slug, name, name_en, epithet, domains, summary, description, sort_order)
select slug, pantheon_slug, name, name_en, epithet, domains, summary, description, sort_order from jsonb_populate_recordset(null::public.figures, $seed$[{"slug":"zeus","pantheon_slug":"greek","name":"제우스","name_en":"Zeus","epithet":"하늘과 번개의 신","domains":["하늘","번개","법과 질서"],"summary":"아버지 크로노스를 몰아내고 올림포스의 신들을 다스리게 된 신들의 왕입니다.","description":["제우스는 형제들과 함께 티탄족과 싸워 이긴 뒤 하늘을 맡았고, 포세이돈은 바다를, 하데스는 저승을 맡았습니다.","번개를 무기로 쓰며 손님과 맹세를 지키는 신으로도 섬겨졌습니다. 로마에서는 유피테르와 동일시되었습니다."],"sort_order":1},{"slug":"athena","pantheon_slug":"greek","name":"아테나","name_en":"Athena","epithet":"지혜와 전략의 여신","domains":["지혜","전쟁의 전략","공예"],"summary":"제우스의 머리에서 완전 무장한 채 태어났다고 전하는 아테네의 수호 여신입니다.","description":["아테나는 무작정 싸우는 전쟁이 아니라 계획과 전략의 전쟁을 맡았고, 베 짜기와 같은 공예의 신이기도 했습니다.","아테네 사람들에게 올리브나무를 선물해 포세이돈을 이기고 도시의 수호신이 되었다는 이야기가 유명합니다."],"sort_order":2},{"slug":"apollo","pantheon_slug":"greek","name":"아폴론","name_en":"Apollo","epithet":"빛과 예언, 음악의 신","domains":["예언","음악","치유","궁술"],"summary":"델포이 신탁의 주인으로, 리라를 연주하는 젊은 신의 모습으로 자주 표현됩니다.","description":["아폴론은 제우스와 레토의 아들이자 아르테미스의 쌍둥이 형제입니다.","델포이에서 왕뱀 피톤을 물리치고 신탁소를 세웠다고 전하며, 사람들은 중요한 일을 앞두고 그곳에서 아폴론의 뜻을 물었습니다."],"sort_order":3},{"slug":"aphrodite","pantheon_slug":"greek","name":"아프로디테","name_en":"Aphrodite","epithet":"사랑과 아름다움의 여신","domains":["사랑","아름다움","욕망"],"summary":"바다 거품에서 태어났다고 전하는 사랑의 여신으로, 로마에서는 베누스라 불렸습니다.","description":["헤시오도스의 「신통기」는 아프로디테가 바다 거품에서 태어났다고 하고, 호메로스는 제우스와 디오네의 딸이라고 합니다.","트로이 전쟁의 발단이 된 ‘파리스의 심판’에서 가장 아름다운 여신으로 뽑혔습니다."],"sort_order":4},{"slug":"poseidon","pantheon_slug":"greek","name":"포세이돈","name_en":"Poseidon","epithet":"바다와 지진의 신","domains":["바다","지진","말"],"summary":"삼지창으로 바다를 다스리고 땅을 뒤흔드는 신입니다.","description":["포세이돈은 제우스의 형제로, 화가 나면 폭풍과 지진을 일으킨다고 여겨졌습니다.","「오디세이아」에서는 아들 폴리페모스의 눈을 멀게 한 오디세우스가 고향에 돌아가지 못하도록 오랫동안 방해합니다."],"sort_order":5},{"slug":"odin","pantheon_slug":"norse","name":"오딘","name_en":"Odin","epithet":"지혜와 죽음, 전쟁의 신","domains":["지혜","시","전쟁","죽음"],"summary":"지혜를 얻으려 한쪽 눈을 내놓은, 아스가르드의 주신입니다.","description":["오딘은 미미르의 샘물을 마시려고 한쪽 눈을 바쳤고, 룬 문자의 비밀을 얻으려 세계수 이그드라실에 아흐레 동안 매달렸다고 합니다.","여덟 다리를 가진 말 슬레이프니르를 타고 다니며, 라그나로크에서 늑대 펜리르에게 삼켜질 운명입니다."],"sort_order":1},{"slug":"thor","pantheon_slug":"norse","name":"토르","name_en":"Thor","epithet":"천둥의 신","domains":["천둥","힘","인간의 수호"],"summary":"망치 묠니르로 거인들과 싸우며 신과 사람의 세계를 지키는 신입니다.","description":["토르는 오딘의 아들로, 염소 두 마리가 끄는 수레를 타고 하늘을 달리면 천둥이 친다고 여겨졌습니다.","라그나로크에서 세계를 휘감은 뱀 요르문간드와 싸워 쓰러뜨리지만, 그 독에 쓰러진다고 전합니다."],"sort_order":2},{"slug":"freyja","pantheon_slug":"norse","name":"프레이야","name_en":"Freyja","epithet":"사랑과 풍요, 마법의 여신","domains":["사랑","풍요","세이드 마법"],"summary":"목걸이 브리싱가멘의 주인이자, 전사한 이들의 절반을 맞이하는 바니르 신족의 여신입니다.","description":["프레이야는 고양이가 끄는 수레를 탄다고 전하며, 전장에서 죽은 이들의 절반을 자신의 저택 폴크방으로 데려갑니다.","난쟁이들이 만든 목걸이 브리싱가멘을 로키가 훔치자 헤임달이 되찾아 돌려주었다는 이야기가 있습니다."],"sort_order":3},{"slug":"loki","pantheon_slug":"norse","name":"로키","name_en":"Loki","epithet":"꾀와 변신의 신","domains":["속임수","변신","혼란"],"summary":"신들을 돕기도, 곤경에 빠뜨리기도 하는 변신의 명수입니다.","description":["로키는 거인의 혈통이지만 아스가르드의 신들과 함께 지냈습니다. 펜리르, 요르문간드, 헬이 그의 자식입니다.","발드르의 죽음을 꾸민 대가로 결박당했다가 라그나로크에 풀려나 신들에게 맞선다고 전합니다."],"sort_order":4},{"slug":"osiris","pantheon_slug":"egyptian","name":"오시리스","name_en":"Osiris","epithet":"저승과 부활의 신","domains":["저승","부활","농경"],"summary":"동생 세트에게 죽임을 당했다가 되살아나 저승의 왕이 된 신입니다.","description":["오시리스는 세트에게 살해되어 몸이 흩어졌지만, 아내 이시스가 조각을 모아 되살렸다고 전합니다.","이후 저승을 다스리며 죽은 이들을 심판했고, 왕관과 갈고리 지팡이, 도리깨를 든 미라의 모습으로 표현됩니다."],"sort_order":1},{"slug":"isis","pantheon_slug":"egyptian","name":"이시스","name_en":"Isis","epithet":"마법과 모성의 여신","domains":["마법","모성","치유"],"summary":"죽은 남편 오시리스를 되살리고 아들 호루스를 지켜 낸 여신입니다.","description":["이시스는 강력한 마법으로 오시리스를 되살렸고, 늪지에 숨어 아들 호루스를 길렀습니다.","아기 호루스에게 젖을 먹이는 이시스의 모습은 이집트 전역에서 소상으로 만들어졌고, 그리스·로마 세계에서도 널리 숭배되었습니다."],"sort_order":2},{"slug":"anubis","pantheon_slug":"egyptian","name":"아누비스","name_en":"Anubis","epithet":"미라와 무덤의 신","domains":["장례","미라","저승 안내"],"summary":"자칼의 머리를 한 신으로, 죽은 이를 저승으로 이끌고 심장의 무게를 단다고 여겨졌습니다.","description":["아누비스는 미라를 만드는 의식을 지키는 신으로, 장례를 맡은 사제들은 그의 가면을 쓰고 의식을 치렀다고 합니다.","「사자의 서」의 심판 장면에서는 죽은 이의 심장을 진리의 깃털과 함께 저울에 올려 무게를 답니다."],"sort_order":3},{"slug":"gilgamesh","pantheon_slug":"mesopotamian","name":"길가메시","name_en":"Gilgamesh","epithet":"우루크의 왕","domains":["영웅","왕권","죽음과 영생"],"summary":"친구 엔키두를 잃고 영원한 삶을 찾아 떠난 우루크의 영웅 왕입니다.","description":["길가메시는 삼분의 이는 신, 삼분의 일은 사람이라고 전하는 우루크의 왕입니다. 실제 왕이었을 가능성도 있습니다.","「길가메시 서사시」에서 그는 엔키두와 함께 괴물 훔바바를 물리치지만, 엔키두가 죽자 죽음을 피하는 길을 찾아 나섭니다."],"sort_order":1},{"slug":"ishtar","pantheon_slug":"mesopotamian","name":"이슈타르","name_en":"Ishtar","epithet":"사랑과 전쟁의 여신","domains":["사랑","전쟁","금성"],"summary":"수메르에서는 인안나라고 불린, 사랑과 전쟁을 함께 다스리는 여신입니다.","description":["이슈타르는 저녁과 새벽의 금성으로 상징되었고, 사자는 그녀의 신성한 동물이었습니다.","저승으로 내려갔다가 돌아오는 「인안나의 저승 하강」 이야기가 유명합니다. 바빌론의 이슈타르 문에는 사자를 새긴 유약 벽돌이 늘어서 있었습니다."],"sort_order":2},{"slug":"marduk","pantheon_slug":"mesopotamian","name":"마르두크","name_en":"Marduk","epithet":"바빌론의 수호신","domains":["창조","왕권","정의"],"summary":"혼돈의 여신 티아마트를 무찌르고 그 몸으로 하늘과 땅을 만든 바빌론의 주신입니다.","description":["창조 서사시 「에누마 엘리시」에서 마르두크는 신들의 왕이 되는 조건으로 티아마트와 싸우겠다고 나섭니다.","바빌론이 강해지면서 마르두크는 메소포타미아의 가장 높은 신이 되었고, 용 모양의 짐승 무슈후슈가 그를 상징합니다."],"sort_order":3},{"slug":"vishnu","pantheon_slug":"hindu","name":"비슈누","name_en":"Vishnu","epithet":"세계를 유지하는 신","domains":["유지","보호","화신(아바타라)"],"summary":"세상의 질서가 무너질 때마다 화신으로 내려와 세계를 지키는 신입니다.","description":["비슈누는 라마와 크리슈나를 비롯한 여러 화신(아바타라)으로 세상에 나타난다고 여겨집니다.","우주가 쉬는 동안 뱀 아난타(셰샤) 위에 누워 잠들어 있다가, 배꼽에서 피어난 연꽃에서 창조의 신 브라흐마가 태어난다고 합니다."],"sort_order":1},{"slug":"shiva","pantheon_slug":"hindu","name":"시바","name_en":"Shiva","epithet":"파괴와 재생의 신","domains":["파괴","재생","고행","춤"],"summary":"낡은 우주를 허물어 새 우주가 태어나게 하는 신으로, 춤의 왕 나타라자로도 표현됩니다.","description":["시바는 히말라야에서 명상하는 고행자이면서, 아내 파르바티와 아들 가네샤, 스칸다를 둔 가장이기도 합니다.","불꽃 고리 안에서 춤추는 나타라자 상은 우주의 창조와 파괴가 이어지는 리듬을 나타냅니다."],"sort_order":2},{"slug":"ganesha","pantheon_slug":"hindu","name":"가네샤","name_en":"Ganesha","epithet":"지혜와 시작의 신","domains":["지혜","시작","장애 제거"],"summary":"코끼리 머리를 한 시바와 파르바티의 아들로, 새로운 일을 시작할 때 먼저 찾는 신입니다.","description":["가네샤가 코끼리 머리를 갖게 된 사연은 여러 가지로 전하는데, 시바가 아들인 줄 모르고 목을 벤 뒤 코끼리 머리를 붙여 주었다는 이야기가 널리 알려져 있습니다.","장애를 없애 주는 신으로 여겨져, 의식이나 새로운 일을 시작할 때 가장 먼저 기도를 받습니다."],"sort_order":3},{"slug":"izanagi-izanami","pantheon_slug":"japanese","name":"이자나기와 이자나미","name_en":"Izanagi & Izanami","epithet":"국토를 낳은 부부 신","domains":["창조","국토","삶과 죽음"],"summary":"하늘의 창으로 바다를 휘저어 첫 섬을 만들고 일본의 섬들과 신들을 낳은 부부 신입니다.","description":["두 신은 하늘에 걸린 다리에 서서 창으로 바다를 휘저었고, 창끝에서 떨어진 소금물이 굳어 첫 섬이 되었다고 합니다.","불의 신을 낳다가 죽은 이자나미를 찾아 이자나기는 저승 요미로 내려가지만, 끝내 데려오지 못하고 돌아옵니다."],"sort_order":1},{"slug":"amaterasu","pantheon_slug":"japanese","name":"아마테라스","name_en":"Amaterasu","epithet":"태양의 여신","domains":["태양","다카마가하라 통치"],"summary":"동굴에 숨어 세상을 어둠에 빠뜨렸다가 신들의 꾀로 다시 나온 태양의 여신입니다.","description":["아마테라스는 이자나기가 저승에서 돌아와 몸을 씻을 때 왼쪽 눈에서 태어났다고 「고사기」는 전합니다.","동생 스사노오의 난폭함에 화가 나 바위 동굴 아마노이와토에 숨자 세상이 어두워졌고, 신들은 동굴 앞에서 춤판을 벌여 그녀를 밖으로 이끌어 냈습니다."],"sort_order":2},{"slug":"susanoo","pantheon_slug":"japanese","name":"스사노오","name_en":"Susanoo","epithet":"폭풍과 바다의 신","domains":["폭풍","바다"],"summary":"하늘에서 쫓겨난 뒤 이즈모에서 머리 여덟 개 달린 큰 뱀 야마타노오로치를 물리친 신입니다.","description":["스사노오는 이자나기의 코에서 태어났다고 전합니다. 다카마가하라에서 난동을 부리다 쫓겨났습니다.","이즈모에서 야마타노오로치에게 술을 먹여 잠재운 뒤 베었고, 그 꼬리에서 나온 검 구사나기를 아마테라스에게 바쳤습니다."],"sort_order":3},{"slug":"raijin","pantheon_slug":"japanese","name":"라이진","name_en":"Raijin","epithet":"번개와 천둥의 신","domains":["천둥","번개","비"],"summary":"북을 둥글게 두르고 두드려 천둥을 울린다고 여겨진 신으로, 바람의 신 후진과 짝을 이룹니다.","description":["라이진은 오니와 비슷한 모습에 북을 고리처럼 둘러멘 모습으로 그려집니다.","바람의 신 후진과 함께 사찰의 문이나 병풍 그림에 자주 등장합니다."],"sort_order":4}]$seed$::jsonb)
on conflict (slug) do nothing;
insert into public.exhibits (id, figure_slug, title, kind, date_label, holder, note, image)
select id, figure_slug, title, kind, date_label, holder, note, image from jsonb_populate_recordset(null::public.exhibits, $seed$[{"id":"zeus-otricoli","figure_slug":"zeus","title":"오트리콜리의 제우스","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/zeus-otricoli.jpg","width":1051,"height":1600,"alt":"곱슬거리는 긴 머리와 풍성한 수염을 한 제우스의 대리석 두상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Zeus_Otricoli_Pio-Clementino_Inv257.jpg"}}},{"id":"athena-giustiniani","figure_slug":"athena","title":"아테나 주스티니아니","kind":"sculpture","date_label":"로마 시대 (그리스 원작의 모작)","holder":"바티칸 박물관 브라초 누오보","note":null,"image":{"src":"/images/exhibits/athena-giustiniani.jpg","width":1006,"height":1600,"alt":"투구를 쓰고 긴 창을 든 채 서 있는 아테나의 대리석 전신상. 발치에 뱀이 감겨 있습니다.","credit":{"artist":"Daderot","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Athena_Giustiniani_-_Braccio_Nuovo,_Museo_Chiaramonti_-_Vatican_Museums_-_DSC00910.jpg"}}},{"id":"apollo-belvedere","figure_slug":"apollo","title":"벨베데레의 아폴론","kind":"sculpture","date_label":"2세기경 (로마 시대 모작)","holder":"바티칸 박물관 피오 클레멘티노관","note":null,"image":{"src":"/images/exhibits/apollo-belvedere.jpg","width":1067,"height":1600,"alt":"곱슬머리를 묶어 올리고 어깨에 망토를 걸친 아폴론 대리석상의 상반신","credit":{"artist":"Marie-Lan Nguyen","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","sourceUrl":"https://commons.wikimedia.org/wiki/File:Belvedere_Apollo_Pio-Clementino_Inv1015_n3.jpg"}}},{"id":"venus-de-milo","figure_slug":"aphrodite","title":"밀로의 비너스","kind":"sculpture","date_label":"기원전 2세기경","holder":"루브르 박물관","note":"밀로스섬에서 발견되었으며, 아프로디테를 표현한 것으로 봅니다.","image":{"src":"/images/exhibits/venus-de-milo.jpg","width":953,"height":1600,"alt":"두 팔이 없고 허리 아래를 천으로 두른 아프로디테의 대리석 상","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Venus_de_Milo_Louvre_Ma399_n4.jpg"}}},{"id":"artemision-bronze","figure_slug":"poseidon","title":"아르테미시온 청동상","kind":"sculpture","date_label":"기원전 460년경","holder":"아테네 국립고고학박물관","note":"손에 든 무기가 사라져 번개를 던지는 제우스인지, 삼지창을 던지는 포세이돈인지 의견이 갈립니다.","image":{"src":"/images/exhibits/artemision-bronze.jpg","width":1067,"height":1600,"alt":"두 팔을 넓게 벌리고 무언가를 던지려는 자세를 한 수염 난 남신 청동상의 상반신","credit":{"artist":"Gary Todd from Xinzheng, China","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ancient_Greece_Bronze_statue_of_Zeus_or_Poseidon;_from_the_sea_near_Cape_Artemision,_Northern_Euboea;_c._460_BC.jpg"}}},{"id":"odin-wanderer","figure_slug":"odin","title":"방랑자 오딘","kind":"painting","date_label":"1886년","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-wanderer.jpg","width":500,"height":733,"alt":"챙 넓은 모자를 눌러쓰고 긴 흰 수염을 늘어뜨린 노인 모습의 오딘이 지팡이를 쥔 흑백 그림","credit":{"artist":"Georg von Rosen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Georg_von_Rosen_-_Oden_som_vandringsman,_1886_(Odin,_the_Wanderer).jpg"}}},{"id":"odin-sleipnir","figure_slug":"odin","title":"궁니르를 들고 슬레이프니르를 탄 오딘","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/odin-sleipnir.jpg","width":686,"height":934,"alt":"긴 수염의 오딘이 창 궁니르를 세워 들고 말 슬레이프니르를 탄 모습을 그린 흑백 선 그림","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Odin_holding_Gungnir_atop_Sleipnir_by_Fr%C3%B8lich.jpg"}}},{"id":"fenrir-odin","figure_slug":"odin","title":"펜리르와 오딘","kind":"print","date_label":"19세기","holder":null,"note":"라그나로크에서 오딘이 늑대 펜리르와 맞서는 장면입니다.","image":{"src":"/images/exhibits/fenrir-odin.jpg","width":1048,"height":627,"alt":"입을 크게 벌린 늑대 펜리르를 향해 창을 들고 말을 달리는 오딘을 덩굴무늬 테두리 안에 그린 흑백 삽화","credit":{"artist":"Lorenz Frølich","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Fenrir_and_Odin_by_Fr%C3%B8lich.jpg"}}},{"id":"thor-jotnar","figure_slug":"thor","title":"거인과 싸우는 토르","kind":"painting","date_label":"1872년","holder":"스웨덴 국립미술관","note":null,"image":{"src":"/images/exhibits/thor-jotnar.jpg","width":1081,"height":1600,"alt":"염소가 끄는 수레 위에서 망치를 치켜든 토르가 번개 속에서 거인들과 싸우는 그림","credit":{"artist":"Mårten Eskil Winge","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Thor%27s_Battle_Against_the_J%C3%B6tnar_(1872)_by_M%C3%A5rten_Eskil_Winge.jpg"}}},{"id":"freyja-brisingamen","figure_slug":"freyja","title":"브리싱가멘을 돌려주는 헤임달","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/freyja-brisingamen.jpg","width":1176,"height":1600,"alt":"왕좌에 앉은 프레이야에게 투구를 쓴 헤임달이 몸을 기울여 목걸이를 건네고, 뒤에서 시녀들이 지켜보는 그림","credit":{"artist":"Nils Jakob Blommér","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Nils_Jakob_Blomm%C3%A9r_-_Heimdall_returns_Brisingamen_to_Freyja_-_Google_Art_Project.jpg"}}},{"id":"osiris-bronze","figure_slug":"osiris","title":"오시리스 청동 소상","kind":"sculpture","date_label":"고대 이집트","holder":"토리노 이집트 박물관","note":null,"image":{"src":"/images/exhibits/osiris-bronze.jpg","width":1102,"height":1600,"alt":"높은 관을 쓰고 두 팔을 가슴 앞에 모은 오시리스의 닳은 청동 소상. 옆에 크기를 재는 자가 놓여 있습니다.","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Osiris_statuette,_bronze_-_Museo_Egizio,_Turin_S_17631_p01.jpg"}}},{"id":"isis-horus","figure_slug":"isis","title":"호루스에게 젖을 먹이는 이시스","kind":"sculpture","date_label":"고대 이집트","holder":"메트로폴리탄 미술관","note":null,"image":{"src":"/images/exhibits/isis-horus.jpg","width":866,"height":1600,"alt":"소뿔과 해 원반 모양의 관을 쓰고 의자에 앉아 무릎 위의 아기 호루스에게 젖을 먹이는 이시스의 소상","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Isis_nursing_Horus_MET_17.190.1641_front.jpg"}}},{"id":"anubis-shrine","figure_slug":"anubis","title":"투탕카멘 무덤의 아누비스 신당","kind":"photograph","date_label":"기원전 14세기 (1920년대 발굴 당시 사진)","holder":"이집트 박물관 (카이로)","note":"하워드 카터의 발굴단 사진가 해리 버턴이 무덤 안에서 찍은 사진입니다.","image":{"src":"/images/exhibits/anubis-shrine.jpg","width":1180,"height":1466,"alt":"투탕카멘 무덤 보물실 입구를 찍은 흑백 사진. 앞쪽 상자 모양 신당 위에 아누비스 조각이 엎드려 있고 뒤로 유물이 쌓여 있습니다.","credit":{"artist":"Harry Burton","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Anubis-shrine_(cropped).jpg"}}},{"id":"weighing-heart","figure_slug":"anubis","title":"심장의 무게 달기 (후네페르의 「사자의 서」)","kind":"manuscript","date_label":"기원전 13세기경","holder":"대영박물관","note":"아누비스가 죽은 이의 심장을 진리의 깃털과 함께 저울에 달고, 토트가 결과를 적습니다. 오른쪽의 괴물 암무트는 심판을 통과하지 못한 심장을 삼킵니다.","image":{"src":"/images/exhibits/weighing-heart.jpg","width":1280,"height":659,"alt":"자칼 머리의 아누비스가 저울로 심장의 무게를 달고, 따오기 머리의 토트가 결과를 적는 장면을 그린 파피루스","credit":{"artist":"Photographed by the British Museum; original artist unknown","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:BD_Weighing_of_the_Heart.jpg"}}},{"id":"hero-lion","figure_slug":"gilgamesh","title":"사자를 제압하는 영웅","kind":"relief","date_label":"기원전 8세기","holder":"루브르 박물관","note":"아시리아 사르곤 2세의 궁전(두르샤루킨) 부조입니다. 길가메시로 보는 견해가 있지만 확실하지 않습니다.","image":{"src":"/images/exhibits/hero-lion.jpg","width":686,"height":1600,"alt":"수염을 기른 영웅이 한 팔로 사자를 끌어안고 다른 손에 무언가를 쥔 모습을 새긴 석조 부조","credit":{"artist":"Unknown artist","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Hero_lion_Dur-Sharrukin_Louvre_AO19862.jpg"}}},{"id":"queen-of-night","figure_slug":"ishtar","title":"밤의 여왕 (버니 부조)","kind":"relief","date_label":"기원전 1800~1750년경","holder":"대영박물관","note":"날개 달린 여신을 이슈타르(인안나)로 보는 견해와 그 언니 에레슈키갈로 보는 견해 등이 있습니다.","image":{"src":"/images/exhibits/queen-of-night.jpg","width":1203,"height":1600,"alt":"날개와 새의 발을 가진 여신이 두 마리 사자 위에 서서 양손에 고리와 막대를 들고, 양옆에 부엉이가 있는 점토 부조","credit":{"artist":null,"license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:British_Museum_Queen_of_the_Night.jpg"}}},{"id":"ishtar-gate-lion","figure_slug":"ishtar","title":"바빌론 행렬로의 사자","kind":"relief","date_label":"기원전 6세기","holder":"이스탄불 고고학 박물관","note":"사자는 이슈타르의 상징으로, 이슈타르 문으로 이어지는 행렬로의 벽을 장식했습니다.","image":{"src":"/images/exhibits/ishtar-gate-lion.jpg","width":1280,"height":854,"alt":"푸른 유약 벽돌 바탕 위로 걸어가는 사자를 새긴 벽돌 부조","credit":{"artist":"Marie-Lan Nguyen","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Lion_Ishtar_gate_IAM_inv88.143.jpg"}}},{"id":"marduk-seal","figure_slug":"marduk","title":"마르두크와 무슈후슈 (원통 인장 도판)","kind":"print","date_label":null,"holder":null,"note":"바빌로니아 원통 인장에 새긴 그림을 옮겨 그린 도판입니다.","image":{"src":"/images/exhibits/marduk-seal.jpg","width":778,"height":1274,"alt":"높은 관을 쓰고 장식이 많은 옷을 입은 마르두크와 그 발치의 용 모양 짐승 무슈후슈를 그린 선 그림","credit":{"artist":"Franz Heinrich Weißbach","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Marduk_and_pet.jpg"}}},{"id":"shiva-nataraja","figure_slug":"shiva","title":"나타라자 (춤추는 시바)","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/shiva-nataraja.jpg","width":1140,"height":1600,"alt":"불꽃 고리 안에서 네 팔을 펼치고 한 다리를 들어 춤추는 시바의 청동상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Shiva_Nataraja,_AK-MAK-187.jpg"}}},{"id":"ganesha-rijks","figure_slug":"ganesha","title":"가네샤","kind":"sculpture","date_label":null,"holder":"암스테르담 국립미술관 (라익스뮤지엄)","note":null,"image":{"src":"/images/exhibits/ganesha-rijks.jpg","width":1132,"height":1600,"alt":"받침 위에 앉은 코끼리 머리의 가네샤를 새긴 석상","credit":{"artist":"Rijksmuseum","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Ganesha,_AK-MAK-237.jpg"}}},{"id":"vishnu-anantashayana","figure_slug":"vishnu","title":"아난타 위에 누운 비슈누","kind":"painting","date_label":"16~17세기","holder":"마탄체리 궁전 (인도 코치)","note":null,"image":{"src":"/images/exhibits/vishnu-anantashayana.jpg","width":1280,"height":1189,"alt":"머리가 여럿인 뱀 아난타 위에 누운 비슈누와 그 주위를 둘러싼 많은 신을 그린 궁전 벽화","credit":{"artist":"Rainer Halama","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mattancherry_Palace-16-17th_Century_mural_paintings-Vishnu_Anantashayana-WUS09329.jpg"}}},{"id":"izanagi-izanami","figure_slug":"izanagi-izanami","title":"일본의 섬들을 만드는 이자나기와 이자나미","kind":"painting","date_label":"1880년대","holder":null,"note":null,"image":{"src":"/images/exhibits/izanagi-izanami.jpg","width":1280,"height":847,"alt":"구름 위에 선 이자나기와 이자나미. 한 신이 구슬 장식이 달린 창을 들고 있습니다.","credit":{"artist":"Kobayashi Eitaku","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Kobayashi_Eitaku_-_Izanami_and_Izanagi_creating_the_Japanese_Islands_alternate_version_HD.jpg"}}},{"id":"amaterasu-iwato","figure_slug":"amaterasu","title":"이와토 가구라의 기원","kind":"print","date_label":"1856년","holder":null,"note":"우타가와 구니사다(3대 도요쿠니)의 세 폭 목판화입니다.","image":{"src":"/images/exhibits/amaterasu-iwato.jpg","width":1280,"height":611,"alt":"세 폭으로 이어진 목판화. 가운데 위쪽에서 빛을 내며 동굴에서 나오는 아마테라스를 신들이 둘러싸고 있습니다.","credit":{"artist":"Toyokuni III","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Origin_of_Iwato_Kagura_Dance_Amaterasu_by_Toyokuni_III_(Kunisada)_1856.png"}}},{"id":"susanoo-orochi","figure_slug":"susanoo","title":"이즈모에서 야마타노오로치를 베는 스사노오","kind":"print","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/susanoo-orochi.jpg","width":1280,"height":633,"alt":"거친 파도 위에서 검을 휘두르는 스사노오와 그에게 달려드는 뱀 야마타노오로치를 그린 목판화","credit":{"artist":"Yoshitoshi","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Susanoo-no-Mikoto-slays-Yamata-no-Orochi-in-Izumo-By-Tsukioka-Yoshitoshi_repaired.png"}}},{"id":"raijin-hokusai","figure_slug":"raijin","title":"뇌신","kind":"painting","date_label":"19세기","holder":null,"note":null,"image":{"src":"/images/exhibits/raijin-hokusai.jpg","width":590,"height":1600,"alt":"족자에 그린 그림. 소용돌이치는 먹구름 속에 붉은 몸의 뇌신이 있습니다.","credit":{"artist":"Katsushika Hokusai","license":"Public domain","licenseUrl":null,"sourceUrl":"https://commons.wikimedia.org/wiki/File:Katsushika_Hokusai_-_Thunder_God_-_Google_Art_Project.jpg"}}}]$seed$::jsonb)
